import pty, os, subprocess, time, struct, termios, fcntl, re, sys

def run_capture(args, send_keys=None, initial_wait=1.0, post_wait=0.5, width=80, height=24, term="xterm-256color"):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", height, width, 0, 0))
    env={**os.environ, "TERM":term}
    p = subprocess.Popen(["./executable"]+args, stdin=slave, stdout=slave, stderr=slave, close_fds=True, env=env)
    os.close(slave)
    os.set_blocking(master, False)
    data=b""
    def drain():
        nonlocal data
        # read for a bit
        end=time.time()+0.3
        while time.time()<end:
            try:
                chunk=os.read(master, 65536)
                if chunk:
                    data+=chunk
                    end=time.time()+0.3
                else:
                    break
            except BlockingIOError:
                time.sleep(0.05)
            except OSError:
                break
    time.sleep(initial_wait)
    drain()
    if send_keys:
        for k in send_keys:
            if isinstance(k, str):
                k=k.encode()
            # k may be tuple (bytes, wait)?
            os.write(master, k)
            time.sleep(post_wait)
            drain()
    # cleanup: send ESC to quit gracefully if still alive
    if p.poll() is None:
        try:
            os.write(master, b"\x1b")
            time.sleep(0.5)
            drain()
        except: pass
    if p.poll() is None:
        try:
            p.terminate()
            p.wait(timeout=2)
        except:
            try: p.kill()
            except: pass
    try: os.close(master)
    except: pass
    return data, p.returncode

def clean_ansi(data: bytes):
    # decode and strip? keep for analysis
    return data.decode('utf-8', errors='replace')

if __name__=="__main__":
    import sys
    args=sys.argv[1:]
    # simple test
    data, rc = run_capture(args)
    print(f"RC={rc} LEN={len(data)}")
    txt=clean_ansi(data)
    print(txt[:10000])
    print("---REPR---")
    print(repr(txt[:5000]))
