import pty, os, subprocess, time, struct, termios, fcntl, re
def start(args, w=80, h=24):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", h, w, 0, 0))
    env={**os.environ, "TERM":"xterm-256color"}
    p = subprocess.Popen(["./executable"]+args, stdin=slave, stdout=slave, stderr=slave, close_fds=True, env=env)
    os.close(slave)
    os.set_blocking(master, False)
    return master, p

def read_avail(master, timeout=0.4):
    data=b""
    end=time.time()+timeout
    while time.time()<end:
        try:
            chunk=os.read(master, 65536)
            if chunk:
                data+=chunk
                # extend a bit?
            else:
                time.sleep(0.02)
        except BlockingIOError:
            time.sleep(0.02)
        except OSError:
            break
    return data

def render(data, rows=24, cols=80):
    txt=data.decode(errors="replace")
    buf=[[" "]*cols for _ in range(rows)]
    cx, cy=0,0
    i=0
    n=len(txt)
    while i<n:
        c=txt[i]
        if c=="\x1b" and i+1<n and txt[i+1]=="[":
            j=i+2
            params=""
            while j<n and (txt[j].isdigit() or txt[j] in ";?"):
                params+=txt[j]; j+=1
            if j<n:
                cmd=txt[j]
                if cmd=="H":
                    parts=params.split(";")
                    try:
                        r=int(parts[0])-1 if parts[0] else 0
                        cc=int(parts[1])-1 if len(parts)>1 and parts[1] else 0
                        cy=max(0,min(rows-1,r)); cx=max(0,min(cols-1,cc))
                    except: pass
                elif cmd=="J" and params=="2":
                    buf=[[" "]*cols for _ in range(rows)]
                i=j+1; continue
        elif c=="\r": cx=0; i+=1; continue
        elif c=="\n": i+=1; continue
        else:
            if 0<=cy<rows and 0<=cx<cols:
                buf[cy][cx]=c; cx+=1
                if cx>=cols: cx=0; cy+=1
                if cy>=rows: cy=rows-1
            i+=1
    return ["".join(r).rstrip() for r in buf]

# Test bogus layouts
for args in [[ "--emu-in","bogus","--emu-out","dvorak"], ["--emu-in","qwerty","--emu-out","bogus"], ["--emu-in","QWERTY","--emu-out","dvorak"], ["--emu-in","qwerty","--emu-out","QWERTY"]]:
    m,p=start(args)
    time.sleep(1.0)
    data=read_avail(m,0.5)
    lines=render(data)
    print(f"ARGS {args} ->")
    for l in lines[8:16]:
        print(f"  |{l}|")
    try: os.write(m,b"\x1b")
    except: pass
    time.sleep(0.4)
    read_avail(m,0.3)
    if p.poll() is None:
        p.terminate()
        try: p.wait(timeout=1)
        except: p.kill()
    try: os.close(m)
    except: pass
    print()

