pub const QWERTY: [[&str; 12]; 3] = [
    ["q","w","e","r","t","y","u","i","o","p","[","]"],
    ["a","s","d","f","g","h","j","k","l",";","'",""],
    ["z","x","c","v","b","n","m",",",".","/","",""],
];
// Actually row2 has 11 keys + empty, row3 10 + 2 empty. Represent as above with empty strings for missing.
// For staggered display, we need to handle empty.
// Let's define as Vec of rows with actual keys:
pub fn get_layout(name: &str) -> [[String; 12]; 3] {
    let lower = name.to_lowercase();
    let base: [[&str; 12]; 3] = match lower.as_str() {
        "qwerty" => [
            ["q","w","e","r","t","y","u","i","o","p","[","]"],
            ["a","s","d","f","g","h","j","k","l",";","'",""],
            ["z","x","c","v","b","n","m",",",".","/","",""],
        ],
        "qwertz" => [
            ["q","w","e","r","t","z","u","i","o","p","ü","+"],
            ["a","s","d","f","g","h","j","k","l","ö","ä",""],
            ["y","x","c","v","b","n","m",",",".","-","",""],
        ],
        "azerty" => [
            ["a","z","e","r","t","y","u","i","o","p","^","$"],
            ["q","s","d","f","g","h","j","k","l","m","ù",""],
            ["w","x","c","v","b","n",",",";",":","!","",""],
        ],
        "dvorak" => [
            ["'"," , ".trim(),".","p","y","f","g","c","r","l","/","="],
            ["a","o","e","u","i","d","h","t","n","s","-",""],
            [";","q","j","k","x","b","m","w","v","z","",""],
        ],
        "colemak" => [
            ["q","w","f","p","g","j","l","u","y",";","[","]"],
            ["a","r","s","t","d","h","n","e","i","o","'",""],
            ["z","x","c","v","b","k","m",",",".","/","",""],
        ],
        "colemakdh" => [
            ["q","w","f","p","b","j","l","u","y",";","[","]"],
            ["a","r","s","t","g","m","n","e","i","o","'",""],
            ["z","x","c","d","v","k","h",",",".","/","",""],
        ],
        _ => [
            ["q","w","e","r","t","y","u","i","o","p","[","]"],
            ["a","s","d","f","g","h","j","k","l",";","'",""],
            ["z","x","c","v","b","n","m",",",".","/","",""],
        ],
    };
    let mut out = [
        [String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new()],
        [String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new()],
        [String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new(),String::new()],
    ];
    for r in 0..3 {
        for c in 0..12 {
            out[r][c] = base[r][c].to_string();
        }
    }
    out
}
