fn run_tui(n_str: String, top: usize, combi: usize, rep: usize, wpm_thresh: u32, acc_thresh: u32, emu_in: String, emu_out: String, show_ortho: bool, nokb: bool, cat: bool) {
    use std::io::Write;
    // Enter alternate screen first (as original does before raw)
    print!("\x1b[?1049h");
    let _ = std::io::stdout().flush();
    // Try enable raw mode
    if crossterm::terminal::enable_raw_mode().is_err() {
        eprintln!("Error: Os {{ code: 6, kind: Uncategorized, message: \"No such device or address\" }}");
        std::process::exit(1);
    }
    // Load pool
    let pool: Vec<String> = load_pool(&n_str, top);
    if pool.is_empty() {
        // Panic as original: src/game.rs:18:45
        let pid = std::process::id();
        // Need to disable raw? No, panic leaves alternate (no restore). Just print panic to stderr and exit 101.
        // Original prints panic to terminal (which is alternate screen). Since stdout/stderr both go to same pty in our test, print to stderr.
        eprintln!("thread 'main' ({}) panicked at src/game.rs:18:45:\ncalled `Option::unwrap()` on a `None` value\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", pid);
        std::process::exit(101);
    }
    // Setup layouts for emu
    let emu_in_layout = if !emu_in.is_empty() { Some(layouts::get_layout(&emu_in)) } else { None };
    let emu_out_layout = if !emu_out.is_empty() { Some(layouts::get_layout(&emu_out)) } else { None };
    // For display, use emu_out if present else qwerty
    let display_layout_name = if !emu_out.is_empty() { emu_out.clone() } else { "qwerty".to_string() };
    // Build emu map: input char (lower) -> output char (lower)
    let mut emu_map: std::collections::HashMap<char, char> = std::collections::HashMap::new();
    if let (Some(in_l), Some(out_l)) = (&emu_in_layout, &emu_out_layout) {
        for r in 0..3 {
            for c in 0..12 {
                let ic = in_l[r][c].chars().next();
                let oc = out_l[r][c].chars().next();
                if let (Some(ic), Some(oc)) = (ic, oc) {
                    // Only map if both non-empty? Empty strings give None, so skip.
                    // For single-char keys (including multibyte like ü, ö, etc., which are single char), map.
                    emu_map.insert(ic, oc);
                    // Also map uppercase? We'll handle case separately.
                }
            }
        }
    }
    // TUI state
    let mut lesson_num: u32 = 1;
    let mut good: u32 = 0;
    let mut bad: u32 = 0;
    let mut wpm_sum: u64 = 0;
    let mut acc_sum: u64 = 0;
    let mut wpm_last: u32 = 0;
    let mut acc_last: u32 = 0;
    let mut lesson = generate_lesson(&pool, combi, rep);
    let mut pos: usize = 0;
    let mut correct_count: u32 = 0;
    let mut total_count: u32 = 0;
    let mut start_time: Option<std::time::Instant> = None;
    let mut typed_errors: Vec<Option<char>> = vec![None; lesson.chars().count()];
    // Initial draw
    let mut size = crossterm::terminal::size().unwrap_or((80,24));
    draw_all(size, lesson_num, good, bad, wpm_thresh, acc_thresh, wpm_sum, lesson_num.saturating_sub(1), acc_sum, wpm_last, acc_last, &lesson, pos, &typed_errors, &display_layout_name, show_ortho, nokb, cat);
    // Input loop
    loop {
        // Poll for events with timeout to handle resize? Use blocking read but handle resize events as they come.
        let ev = match crossterm::event::read() {
            Ok(e) => e,
            Err(_) => continue,
        };
        match ev {
            crossterm::event::Event::Resize(nw, nh) => {
                size = (nw, nh);
                draw_all(size, lesson_num, good, bad, wpm_thresh, acc_thresh, wpm_sum, lesson_num.saturating_sub(1), acc_sum, wpm_last, acc_last, &lesson, pos, &typed_errors, &display_layout_name, show_ortho, nokb, cat);
            }
            crossterm::event::Event::Key(key) => {
                // Handle quit: Esc or Ctrl-C
                if key.code == crossterm::event::KeyCode::Esc {
                    cleanup_and_exit(0);
                }
                if key.code == crossterm::event::KeyCode::Char('c') && key.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) {
                    cleanup_and_exit(0);
                }
                // Also Ctrl-C may come as KeyCode::Char('c') with CONTROL? Handled. What about KeyCode::Char('C')? No.
                // Handle other keys
                let input_char: Option<char> = match key.code {
                    crossterm::event::KeyCode::Char(c) => {
                        // Ignore if Alt or Ctrl (except Ctrl-C handled)? For Ctrl+letter (other than c?), ignore? Original ignores? Let's ignore any with CONTROL or ALT.
                        if key.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) || key.modifiers.contains(crossterm::event::KeyModifiers::ALT) {
                            None
                        } else {
                            Some(c)
                        }
                    }
                    crossterm::event::KeyCode::Enter => Some(' '), // Enter as space (original treats Enter as space)
                    _ => None, // Ignore Backspace, Tab, arrows, etc.
                };
                if let Some(ch) = input_char {
                    // Translate via emu if needed
                    let translated: Option<char> = if !emu_in.is_empty() {
                        if ch == ' ' {
                            Some(' ')
                        } else {
                            // Find mapping (case-insensitive for letters, but preserve case for output)
                            let lower = ch.to_lowercase().next().unwrap_or(ch);
                            if let Some(&out_lower) = emu_map.get(&lower) {
                                // out_lower is lowercase (or punct). If original ch was uppercase and out_lower is alphabetic, uppercase it.
                                if ch.is_uppercase() && out_lower.is_alphabetic() {
                                    Some(out_lower.to_uppercase().next().unwrap_or(out_lower))
                                } else {
                                    Some(out_lower)
                                }
                            } else {
                                // Not in map (e.g., digits, or chars not in layout) -> ignore? Actually for inputs not in map, ignore (as observed for digits).
                                // But what about space? Already handled. For other punct not in map? All punct in layouts are in map, so they will translate. Digits not in map -> None -> ignore.
                                None
                            }
                        }
                    } else {
                        Some(ch)
                    };
                    if let Some(tch) = translated {
                        // Check if tch is processable: only alphabetic (a-z, A-Z) or space? Original ignores punct/digits (translated output punct -> ignore).
                        // How to determine? Check if tch is alphabetic or space? What about uppercase? Yes.
                        // For lesson containing punct/digits (from file), typing those punct/digits will be ignored (since tch punct -> ignore), so lesson impossible. That's as observed.
                        let is_processable = tch == ' ' || tch.is_alphabetic();
                        // Note: is_alphabetic includes unicode letters like ü, ö, etc. Those are in layouts (qwertz etc.) and lessons never contain them (since ngrams are ascii), but if lesson did contain them (via file with ü?), typing ü would be processable? Probably yes (since is_alphabetic true). Good.
                        if !is_processable {
                            continue;
                        }
                        // Process typing at pos
                        let lesson_chars: Vec<char> = lesson.chars().collect();
                        if pos >= lesson_chars.len() {
                            continue;
                        }
                        if start_time.is_none() {
                            start_time = Some(std::time::Instant::now());
                        }
                        total_count += 1;
                        let expected = lesson_chars[pos];
                        if tch == expected {
                            correct_count += 1;
                            // Display green at pos
                            draw_typed_char(size, &lesson, pos, expected, true, tch, &display_layout_name, show_ortho, nokb, cat);
                        } else {
                            // Display red expected at pos, grey typed at second line
                            draw_typed_char_wrong(size, &lesson, pos, expected, tch, &display_layout_name, show_ortho, nokb, cat);
                        }
                        pos += 1;
                        // Move cursor to next pos (draw cursor)
                        draw_cursor(size, &lesson, pos);
                        if pos >= lesson_chars.len() {
                            // Lesson complete: compute WPM/Acc
                            let elapsed = start_time.unwrap().elapsed().as_secs_f64();
                            if elapsed < 0.001 { elapsed = 0.001; } // avoid div by zero? Original? For very fast, WPM huge. Use max?
                            let non_space = lesson_chars.iter().filter(|&&c| c != ' ').count() as f64;
                            let wpm = ((non_space / 5.0) / (elapsed / 60.0)) as u32;
                            let acc = if total_count == 0 { 100 } else { (correct_count as f64 / total_count as f64 * 100.0) as u32 };
                            wpm_last = wpm;
                            acc_last = acc;
                            wpm_sum += wpm as u64;
                            acc_sum += acc as u64;
                            let success = wpm >= wpm_thresh && acc >= acc_thresh;
                            if success { good += 1; } else { bad += 1; }
                            lesson_num += 1;
                            // Generate new lesson
                            lesson = generate_lesson(&pool, combi, rep);
                            pos = 0;
                            correct_count = 0;
                            total_count = 0;
                            start_time = None;
                            typed_errors = vec![None; lesson.chars().count()];
                            // Redraw all (lesson, stats, header)
                            // Need to get current size (may have changed)
                            size = crossterm::terminal::size().unwrap_or(size);
                            draw_all(size, lesson_num, good, bad, wpm_thresh, acc_thresh, wpm_sum, lesson_num.saturating_sub(1)-0, acc_sum, wpm_last, acc_last, &lesson, pos, &typed_errors, &display_layout_name, show_ortho, nokb, cat);
                            // Note: draw_all needs avg calculation: wpm_sum / num_lessons? num_lessons = lesson_num-1
                        }
                    } else {
                        // Ignored (translated None)
                        continue;
                    }
                } else {
                    // Ignored key (arrows, etc.)
                    continue;
                }
            }
            _ => {}
        }
        // Check size change via polling? crossterm Resize events will come as Event::Resize. Good.
        // Also need to handle terminal resize that doesn't generate event? Poll size each loop? Our loop blocks on read(), so resize events will be delivered as events. Good.
    }
}

fn load_pool(n_str: &str, top: usize) -> Vec<String> {
    if n_str == "2" {
        let mut v: Vec<String> = ngrams::BIGRAMS.iter().map(|s| s.to_string()).collect();
        v.truncate(top.min(v.len()));
        v
    } else if n_str == "3" {
        let mut v: Vec<String> = ngrams::TRIGRAMS.iter().map(|s| s.to_string()).collect();
        v.truncate(top.min(v.len()));
        v
    } else if n_str == "4" {
        let mut v: Vec<String> = ngrams::TETRAGRAMS.iter().map(|s| s.to_string()).collect();
        v.truncate(top.min(v.len()));
        v
    } else if n_str == "w" {
        let mut v: Vec<String> = ngrams::WORDS.iter().map(|s| s.to_string()).collect();
        v.truncate(top.min(v.len()));
        v
    } else {
        // file
        let content = std::fs::read_to_string(n_str).unwrap_or_default();
        let mut tokens: Vec<String> = Vec::new();
        for line in content.lines() {
            for part in line.split(',') {
                let filtered: String = part.chars().filter(|c| !c.is_control()).collect();
                tokens.push(filtered);
            }
        }
        // If file was empty (no lines), tokens empty -> panic later. Note: content.lines() for "" gives empty, for "\n" gives [""].
        tokens.truncate(top.min(tokens.len().max(1)));
        // Actually truncate to top, but if top > len, use all.
        if top < tokens.len() {
            tokens.truncate(top);
        }
        tokens
    }
}

fn generate_lesson(pool: &[String], combi: usize, rep: usize) -> String {
    use rand::seq::SliceRandom;
    use rand::thread_rng;
    let mut rng = thread_rng();
    let mut picked: Vec<String> = Vec::new();
    for _ in 0..combi {
        if let Some(choice) = pool.choose(&mut rng) {
            picked.push(choice.clone());
        }
    }
    let mut repeated: Vec<String> = Vec::new();
    for _ in 0..rep {
        for p in &picked {
            repeated.push(p.clone());
        }
    }
    let mut s = repeated.join(" ");
    s.push(' ');
    s
}

fn cleanup_and_exit(code: i32) -> ! {
    let _ = crossterm::terminal::disable_raw_mode();
    print!("\x1b[?1049l");
    let _ = std::io::Write::flush(&mut std::io::stdout());
    // Show cursor? Original exit shows ?25h? Actually after ?1049l, no ?25h? Let's check: exit snippet ends with ?1049l without ?25h? Hmm. Our earlier exit snippet ended with ?1049l (no ?25h). But to be safe, show cursor.
    // Original exit: after ?1049l, does it show cursor? The snippet ended with ?1049l, no ?25h. So don't show.
    std::process::exit(code);
}

