                            if elapsed < 0.001 { elapsed = 0.001; } // avoid div by zero? Original? For very fast, WPM huge. Use max?
                            let non_space = lesson_chars.iter().filter(|&&c| c != ' ').count() as f64;
                            let wpm = ((non_space / 5.0) / (elapsed / 60.0)) as u32;
                            let acc = if total_count == 0 { 100 } else { (correct_count as f64 / total_count as f64 * 100.0) as u32 };
                            wpm_last = wpm;
                            acc_last = acc;
                            wpm_sum += wpm as u64;
                            acc_sum += acc as u64;
                            let success = wpm >= wpm_thresh && acc >= acc_thresh;
                            if success { good += 1; } else { bad += 1; }
                            lesson_num += 1;
                            // Generate new lesson
                            lesson = generate_lesson(&pool, combi, rep);
                            pos = 0;
                            correct_count = 0;
                            total_count = 0;
                            start_time = None;
                            typed_errors = vec![None; lesson.chars().count()];
                            // Redraw all (lesson, stats, header)
                            // Need to get current size (may have changed)
                            size = crossterm::terminal::size().unwrap_or(size);
                            draw_all(size, lesson_num, good, bad, wpm_thresh, acc_thresh, wpm_sum, lesson_num.saturating_sub(1)-0, acc_sum, wpm_last, acc_last, &lesson, pos, &typed_errors, &display_layout_name, show_ortho, nokb, cat);
