            if let Ok(ev) = crossterm::event::read() {
                match ev {
                    crossterm::event::Event::Key(k) => {
                        if k.code == crossterm::event::KeyCode::Esc { break; }
                        if k.code == crossterm::event::KeyCode::Char('c') && k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) { break; }
                    }
                    crossterm::event::Event::Resize(nw, nh) => {
                        if nw >= 80 && nh >= need_h {
                            break;
                        } else {
                            draw_resize((nw,nh), nokb);
                        }
                    }
                    _ => {}
                }
            }
        }
        // After resize to large enough, continue to main UI (need to re-check size and draw)
        let (w1, h1) = crossterm::terminal::size().unwrap_or((80,24));
        if w1 < 80 || h1 < need_h {
            let _ = crossterm::terminal::disable_raw_mode();
            print!("\x1b[?1049l");
            let _ = std::io::stdout().flush();
            std::process::exit(0);
        }
        // Fall through to main UI with new size
    }
    // Setup emu map
    let emu_in_layout = if !emu_in.is_empty() { Some(crate::layouts::get_layout(&emu_in)) } else { None };
    let emu_out_layout = if !emu_out.is_empty() { Some(crate::layouts::get_layout(&emu_out)) } else { None };
    let display_layout_name = if !emu_out.is_empty() { emu_out.clone() } else { "qwerty".to_string() };
    let mut emu_map: std::collections::HashMap<char, char> = std::collections::HashMap::new();
    if let (Some(in_l), Some(out_l)) = (&emu_in_layout, &emu_out_layout) {
        for r in 0..3 {
            for c in 0..12 {
                if let (Some(ic), Some(oc)) = (in_l[r][c].chars().next(), out_l[r][c].chars().next()) {
                    emu_map.insert(ic, oc);
                }
            }
        }
    }
    let mut lesson_num: u32 = 1;
    let mut good: u32 = 0;
    let mut bad: u32 = 0;
    let mut wpm_sum: u64 = 0;
    let mut acc_sum: u64 = 0;
    let mut wpm_last: u32 = 0;
    let mut acc_last: u32 = 0;
    let mut lesson = generate_lesson(&pool, combi, rep);
    let mut pos: usize = 0;
    let mut correct_count: u32 = 0;
    let mut total_count: u32 = 0;
    let mut start_time: Option<std::time::Instant> = None;
    let mut typed_errors: Vec<Option<char>> = vec![None; lesson.chars().count()];
    let mut size = crossterm::terminal::size().unwrap_or((80,24));
    draw_all(size, lesson_num, good, bad, wpm_thresh, acc_thresh, wpm_sum, 0, acc_sum, wpm_last, acc_last, &lesson, pos, &typed_errors, &display_layout_name, show_ortho, nokb, cat);
    loop {
        let ev = match crossterm::event::read() {
            Ok(e) => e,
            Err(_) => continue,
        };
        match ev {
            crossterm::event::Event::Resize(nw, nh) => {
                size = (nw, nh);
                let need_h2 = if nokb { 13 } else { 20 };
                if nw < 80 || nh < need_h2 {
                    draw_resize((nw,nh), nokb);
                } else {
                    draw_all(size, lesson_num, good, bad, wpm_thresh, acc_thresh, wpm_sum, lesson_num.saturating_sub(1), acc_sum, wpm_last, acc_last, &lesson, pos, &typed_errors, &display_layout_name, show_ortho, nokb, cat);
                }
            }
            crossterm::event::Event::Key(key) => {
                // If currently in resize mode (small terminal), only handle quit, ignore typing
                let (cw, chh) = crossterm::terminal::size().unwrap_or(size);
                let need_h3 = if nokb { 13 } else { 20 };
                let in_resize = cw < 80 || chh < need_h3;
                if key.code == crossterm::event::KeyCode::Esc {
                    let _ = crossterm::terminal::disable_raw_mode();
                    print!("\x1b[?1049l");
                    let _ = std::io::stdout().flush();
                    std::process::exit(0);
                }
                if key.code == crossterm::event::KeyCode::Char('c') && key.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) {
                    let _ = crossterm::terminal::disable_raw_mode();
                    print!("\x1b[?1049l");
                    let _ = std::io::stdout().flush();
                    std::process::exit(0);
                }
                if in_resize {
                    continue;
                }
                let input_char: Option<char> = match key.code {
                    crossterm::event::KeyCode::Char(c) => {
                        if key.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) || key.modifiers.contains(crossterm::event::KeyModifiers::ALT) {
                            None
                        } else { Some(c) }
                    }
                    crossterm::event::KeyCode::Enter => Some(' '),
                    _ => None,
                };
                if let Some(ch) = input_char {
                    let translated: Option<char> = if !emu_in.is_empty() {
                        if ch == ' ' { Some(' ') }
                        else {
                            let lower = ch.to_lowercase().next().unwrap_or(ch);
                            if let Some(&out_lower) = emu_map.get(&lower) {
                                if ch.is_uppercase() && out_lower.is_alphabetic() {
                                    Some(out_lower.to_uppercase().next().unwrap_or(out_lower))
                                } else { Some(out_lower) }
                            } else { None }
                        }
                    } else { Some(ch) };
                    if let Some(tch) = translated {
                        if tch != ' ' && !tch.is_alphabetic() {
                            continue;
                        }
                        let lesson_chars: Vec<char> = lesson.chars().collect();
                        if pos >= lesson_chars.len() { continue; }
                        if start_time.is_none() { start_time = Some(std::time::Instant::now()); }
                        total_count += 1;
                        let expected = lesson_chars[pos];
                        if tch == expected {
                            correct_count += 1;
                            draw_correct(size, &lesson, pos, expected, &display_layout_name, show_ortho, nokb, cat);
                        } else {
                            draw_wrong(size, &lesson, pos, expected, tch);
                        }
                        if tch != expected {
                            if pos < typed_errors.len() { typed_errors[pos] = Some(tch); }
                        }
                        pos += 1;
                        draw_cursor_for(size, &lesson, pos);
                        if pos >= lesson_chars.len() {
                            let elapsed = start_time.unwrap().elapsed().as_secs_f64().max(0.001);
                            let non_space = lesson_chars.iter().filter(|&&c| c != ' ').count() as f64;
                            let wpm = ((non_space / 5.0) / (elapsed / 60.0)) as u32;
                            let acc = if total_count == 0 { 100 } else { (correct_count as f64 / total_count as f64 * 100.0) as u32 };
                            wpm_last = wpm; acc_last = acc;
                            wpm_sum += wpm as u64; acc_sum += acc as u64;
                            if wpm >= wpm_thresh && acc >= acc_thresh { good += 1; } else { bad += 1; }
                            lesson_num += 1;
                            lesson = generate_lesson(&pool, combi, rep);
                            pos = 0; correct_count = 0; total_count = 0; start_time = None;
                            typed_errors = vec![None; lesson.chars().count()];
                            size = crossterm::terminal::size().unwrap_or(size);
                            draw_all(size, lesson_num, good, bad, wpm_thresh, acc_thresh, wpm_sum, lesson_num-1, acc_sum, wpm_last, acc_last, &lesson, pos, &typed_errors, &display_layout_name, show_ortho, nokb, cat);
                        }
                    }
                }
            }
            _ => {}
        }
    }
}
